function setupModifierControls(database) {
  setupModifierControl(
    "a",
    "prefix"
  );
  setupModifierControl(
    "a",
    "suffix"
  );
  setupModifierControl(
    "b",
    "prefix"
  );
  setupModifierControl(
    "b",
    "suffix"
  );
}
function setupModifierControl(itemKey, modifierType, database) {
  const select = getModifierSelect(
    itemKey,
    modifierType
  );
  const button = getModifierAddButton(
    itemKey,
    modifierType
  );
  if (!select || !button) {
    return;
  }
  button.addEventListener(
    "click",
    async () => {
      const item = itemKey === "a" ? state.itemA : state.itemB;
      const maximum = modifierType === "prefix" ? MAX_PREFIXES : MAX_SUFFIXES;
      const collection = modifierType === "prefix" ? item.prefixes : item.suffixes;
      if (collection.length >= maximum) {
        return;
      }
      const modId = select.value;
      if (!modId) {
        return;
      }
      if (collection.some(
        (mod2) => getModifierId(mod2) === modId
      )) {
        return;
      }
      const chunk = await loadModChunk(
        item.baseType
      );
      if (!chunk) {
        return;
      }
      const mod = chunk.MODS?.[modId];
      if (!mod) {
        return;
      }
      collection.push(
        normalizeSelectedModifier(
          mod
        )
      );
      select.value = "";
      updateModifierSelectors(
        itemKey
      );
      renderSelectedModifiers(
        itemKey,
        modifierType
      );
    }
  );
}
async function updateModifierSelectors(itemKey) {
  const item = itemKey === "a" ? state.itemA : state.itemB;
  if (!item.baseType || !item.baseId) {
    clearModifierSelect(
      itemKey,
      "prefix"
    );
    clearModifierSelect(
      itemKey,
      "suffix"
    );
    renderSelectedModifiers(
      itemKey,
      "prefix"
    );
    renderSelectedModifiers(
      itemKey,
      "suffix"
    );
    return;
  }
  const chunk = await loadModChunk(
    item.baseType
  );
  if (!chunk) {
    return;
  }
  const baseMods = chunk.MODS_BY_BASE?.[item.baseId] ?? [];
  populateModifierSelect(
    itemKey,
    "prefix",
    baseMods,
    chunk.MODS
  );
  populateModifierSelect(
    itemKey,
    "suffix",
    baseMods,
    chunk.MODS
  );
  renderSelectedModifiers(
    itemKey,
    "prefix"
  );
  renderSelectedModifiers(
    itemKey,
    "suffix"
  );
}
const INFLUENCE_ALIASES = {
  shaper: "shaper",
  elder: "elder",
  crusader: "crusader",
  adjudicator: "crusader",
  redeemer: "redeemer",
  eyrie: "redeemer",
  hunter: "hunter",
  basilisk: "hunter",
  warlord: "warlord",
  eater: "eater",
  eater_of_worlds: "eater",
  exarch: "exarch",
  searing_exarch: "exarch"
};
function getModifierInfluence(generationType) {
  const value = String(
    generationType ?? ""
  ).toLowerCase();
  const match = value.match(
    /^(?:prefix|suffix)_(.+)$/
  );
  if (!match) {
    return null;
  }
  return INFLUENCE_ALIASES[match[1]] ?? null;
}
function modifierMatchesItemInfluence(item, ref, mod) {
  const requiredInfluence = getModifierInfluence(
    ref?.generationType ?? mod?.generationType ?? ""
  );
  if (!requiredInfluence) {
    return true;
  }
  const itemInfluences = Array.isArray(
    item?.influences
  ) ? item.influences : [];
  return itemInfluences.includes(
    requiredInfluence
  );
}
function populateModifierSelect(itemKey, modifierType, baseMods, mods) {
  const select = getModifierSelect(
    itemKey,
    modifierType
  );
  if (!select) {
    return;
  }
  const item = itemKey === "a" ? state.itemA : state.itemB;
  const collection = modifierType === "prefix" ? item.prefixes : item.suffixes;
  const maximum = modifierType === "prefix" ? MAX_PREFIXES : MAX_SUFFIXES;
  select.innerHTML = `
    <option value="">
      ${collection.length >= maximum ? `Maximum ${maximum} reached` : `Select ${modifierType}...`}
    </option>
  `;
  if (collection.length >= maximum) {
    select.disabled = true;
    return;
  }
  const candidates = baseMods.filter(
    (ref) => {
      if (!ref) {
        return false;
      }
      const generationType = String(
        ref.generationType ?? ""
      );
      const isCorrectType = generationType === modifierType || generationType.startsWith(
        `${modifierType}_`
      );
      if (!isCorrectType) {
        return false;
      }
      const mod = mods?.[ref.id];
      if (!modifierMatchesItemInfluence(
        item,
        ref,
        mod
      )) {
        return false;
      }
      const weight = Number(
        ref.weight
      );
      if (Number.isFinite(weight) && weight <= 0) {
        return false;
      }
      const modId = ref.id;
      if (collection.some(
        (mod2) => getModifierId(mod2) === modId
      )) {
        return false;
      }
      return Boolean(
        mods?.[modId]
      );
    }
  ).sort(
    (a, b) => {
      const nameA = mods[a.id]?.name ?? a.id;
      const nameB = mods[b.id]?.name ?? b.id;
      return nameA.localeCompare(
        nameB
      );
    }
  );
  for (const ref of candidates) {
    const mod = mods[ref.id];
    const option = document.createElement(
      "option"
    );
    option.value = ref.id;
    option.textContent = formatModifierOption(
      mod,
      ref
    );
    select.appendChild(
      option
    );
  }
  select.disabled = candidates.length === 0;
}
function formatModifierOption(mod, ref) {
  const name = mod?.name || ref?.id || "Unknown modifier";
  const tier = getModifierTier(
    mod,
    ref
  );
  const weight = Number(
    ref?.weight
  );
  const details = [];
  if (tier !== null) {
    details.push(
      `T${tier}`
    );
  }
  if (Number.isFinite(weight)) {
    details.push(
      `weight ${weight}`
    );
  }
  if (ref?.group) {
    details.push(
      ref.group
    );
  }
  return details.length ? `${name} (${details.join(" • ")})` : name;
}
function getModifierTier(mod, ref) {
  if (Number.isInteger(
    ref?.tier
  )) {
    return ref.tier;
  }
  if (Number.isInteger(
    mod?.tier
  )) {
    return mod.tier;
  }
  return null;
}
function updateModifierCount(itemKey, modifierType) {
  const item = itemKey === "a" ? state.itemA : state.itemB;
  const collection = modifierType === "prefix" ? item.prefixes : item.suffixes;
  const maximum = modifierType === "prefix" ? MAX_PREFIXES : MAX_SUFFIXES;
  const count = document.querySelector(
    `#item-${itemKey}-${modifierType}-count`
  );
  if (!count) {
    return;
  }
  count.textContent = `${collection.length} / ${maximum}`;
}
function renderSelectedModifiers(itemKey, modifierType) {
  const item = itemKey === "a" ? state.itemA : state.itemB;
  const collection = modifierType === "prefix" ? item.prefixes : item.suffixes;
  const list = getModifierListElement(
    itemKey,
    modifierType
  );
  updateModifierCount(
    itemKey,
    modifierType
  );
  if (!list) {
    return;
  }
  list.innerHTML = "";
  if (collection.length === 0) {
    list.innerHTML = `
      <div class="empty-mods">
        No ${modifierType}s selected.
      </div>
    `;
    return;
  }
  for (let index = 0; index < collection.length; index++) {
    const mod = collection[index];
    const row = document.createElement(
      "div"
    );
    row.className = "selected-mod";
    const name = mod.name || mod.id || "Unknown modifier";
    const details = [];
    if (mod.generationType) {
      details.push(
        formatGenerationType(
          mod.generationType
        )
      );
    }
    if (mod.group) {
      details.push(
        mod.group
      );
    }
    row.innerHTML = `
      <div class="selected-mod-info">

        <strong>
          ${escapeHtml(name)}
        </strong>

        ${details.length ? `
              <small>
                ${escapeHtml(
      details.join(" • ")
    )}
              </small>
            ` : ""}

      </div>

      <button
        type="button"
        class="remove-mod-button"
        data-item="${itemKey}"
        data-type="${modifierType}"
        data-index="${index}"
      >
        Remove
      </button>
    `;
    const removeButton = row.querySelector(
      ".remove-mod-button"
    );
    removeButton.addEventListener(
      "click",
      () => {
        collection.splice(
          index,
          1
        );
        updateModifierSelectors(
          itemKey
        );
        renderSelectedModifiers(
          itemKey,
          modifierType
        );
      }
    );
    list.appendChild(
      row
    );
  }
}
function formatGenerationType(value) {
  return String(
    value
  ).replaceAll(
    "_",
    " "
  ).replace(
    /\b\w/g,
    (char) => char.toUpperCase()
  );
}
function clearModifierUI(itemKey) {
  clearModifierSelect(
    itemKey,
    "prefix"
  );
  clearModifierSelect(
    itemKey,
    "suffix"
  );
  renderSelectedModifiers(
    itemKey,
    "prefix"
  );
  renderSelectedModifiers(
    itemKey,
    "suffix"
  );
}
function clearModifierSelect(itemKey, modifierType) {
  const select = getModifierSelect(
    itemKey,
    modifierType
  );
  if (!select) {
    return;
  }
  select.innerHTML = `
    <option value="">
      Select ${modifierType}...
    </option>
  `;
  select.disabled = true;
}
function getModifierSelect(itemKey, modifierType) {
  return document.querySelector(
    `#item-${itemKey}-${modifierType}-select`
  );
}
function getModifierAddButton(itemKey, modifierType) {
  return document.querySelector(
    `#item-${itemKey}-${modifierType}-add`
  );
}
function getModifierListElement(itemKey, modifierType) {
  return document.querySelector(
    `#item-${itemKey}-${modifierType}-list`
  );
}
function normalizeSelectedModifier(mod) {
  return {
    id: mod.id,
    name: mod.name ?? mod.id,
    generationType: mod.generationType ?? null,
    group: mod.group ?? null,
    domain: mod.domain ?? null,
    tags: Array.isArray(mod.tags) ? [...mod.tags] : [],
    stats: Array.isArray(mod.stats) ? structuredClone(
      mod.stats
    ) : [],
    levels: Array.isArray(mod.levels) ? structuredClone(
      mod.levels
    ) : [],
    weights: Array.isArray(mod.weights) ? structuredClone(
      mod.weights
    ) : [],
    spawnWeights: Array.isArray(
      mod.spawnWeights
    ) ? structuredClone(
      mod.spawnWeights
    ) : [],
    requiredLevel: Number.isFinite(
      Number(
        mod.requiredLevel
      )
    ) ? Number(
      mod.requiredLevel
    ) : null
  };
}
function getModifierId(mod) {
  if (typeof mod === "string") {
    return mod;
  }
  return mod?.id ?? null;
}
function setupRunButton(database) {
  const button = document.querySelector(
    "#run-simulation"
  );
  if (!button) {
    return;
  }
  button.addEventListener(
    "click",
    () => {
      const output = document.querySelector(
        "#simulation-output"
      );
      try {
        const result = recombine({
          itemA: state.itemA,
          itemB: state.itemB,
          database
        });
        output.className = "simulation-output success";
        output.innerHTML = `
          <div class="result-title">
            Recombination Result
          </div>

          <div>
            <strong>Base Type:</strong>
            ${escapeHtml(
          getBaseTypeName(
            result.baseType
          )
        )}
          </div>

          <div>
            <strong>Base:</strong>
            ${escapeHtml(
          result.base
        )}
          </div>

          <div>
            <strong>Item Level:</strong>
            ${escapeHtml(
          result.itemLevel
        )}
          </div>

          <div>
            <strong>Influence:</strong>
            ${result.influences?.length ? escapeHtml(
          result.influences.join(
            ", "
          )
        ) : "None"}
          </div>

          <div class="result-section">

            <strong>
              Prefixes
            </strong>

            <pre>${escapeHtml(
          JSON.stringify(
            result.prefixes,
            null,
            2
          )
        )}</pre>

          </div>

          <div class="result-section">

            <strong>
              Suffixes
            </strong>

            <pre>${escapeHtml(
          JSON.stringify(
            result.suffixes,
            null,
            2
          )
        )}</pre>

          </div>
        `;
      } catch (error) {
        output.className = "simulation-output error";
        output.textContent = error?.message ?? String(error);
      }
    }
  );
}
function renderStatus() {
  const status = document.querySelector(
    "#base-type-status"
  );
  if (!status) {
    return;
  }
  if (!state.itemA.baseType) {
    status.textContent = "Select a base type for Item A.";
    status.className = "status";
    return;
  }
  if (!state.itemA.baseId) {
    status.textContent = "Select a base for Item A.";
    status.className = "status";
    return;
  }
  if (!state.itemB.baseId) {
    status.textContent = "Select a base for Item B.";
    status.className = "status";
    return;
  }
  status.textContent = "Item B is restricted to the same base type.";
  status.className = "status locked";
}
function getBaseTypeName(id) {
  return BASE_TYPES.find(
    (type) => type.id === id
  )?.name ?? id;
}
function escapeHtml(value) {
  return String(
    value
  ).replaceAll(
    "&",
    "&amp;"
  ).replaceAll(
    "<",
    "&lt;"
  ).replaceAll(
    ">",
    "&gt;"
  ).replaceAll(
    '"',
    "&quot;"
  ).replaceAll(
    "'",
    "&#039;"
  );
}
document.addEventListener("DOMContentLoaded", () => {
  initializeUI({ database: DATABASE });
});
